// Server-only publications loader — reads data/root-publications.json.
//
// This module provides access to the publication decisions generated by the
// batch review pipeline (scripts/review-roots.ts). It validates the schema
// and caches the result across HMR reloads.
//
// The publications file is generated by the pipeline and tracks which roots
// are eligible for public display. It is separate from ROOT_ALLOWLIST, which
// tracks human review status. A root may be published by the automated
// pipeline even while still pending human review in ROOT_ALLOWLIST.

import path from "node:path";
import fs from "node:fs";
import type { PublicationDecision } from "./publication-policy";

export type { PublicationDecision };

const DATA_DIR = path.join(process.cwd(), "data");
const PUBLICATIONS_PATH = path.join(DATA_DIR, "root-publications.json");

// Cache across HMR reloads
const cache = (
  globalThis as unknown as {
    __alhudaPublications?: {
      decisions: Map<string, PublicationDecision> | null;
    };
  }
).__alhudaPublications ?? { decisions: null };
(globalThis as unknown as { __alhudaPublications?: typeof cache }).__alhudaPublications =
  cache;

/**
 * Load publication decisions from disk. Returns cached data if available.
 * Validates the schema and drops invalid entries.
 */
export function loadPublications(): Map<string, PublicationDecision> {
  if (cache.decisions) return cache.decisions;

  if (!fs.existsSync(PUBLICATIONS_PATH)) {
    cache.decisions = new Map();
    return cache.decisions;
  }

  try {
    const raw = fs.readFileSync(PUBLICATIONS_PATH, "utf-8");
    const data = JSON.parse(raw);

    if (!Array.isArray(data)) {
      console.error("Publications file is not an array");
      cache.decisions = new Map();
      return cache.decisions;
    }

    const decisions = new Map<string, PublicationDecision>();
    for (const item of data) {
      if (
        item &&
        typeof item === "object" &&
        typeof item.slug === "string" &&
        typeof item.root === "string" &&
        (item.decision === "publish" ||
          item.decision === "withhold" ||
          item.decision === "needs-review") &&
        Array.isArray(item.reasons) &&
        Array.isArray(item.includedLemmas) &&
        item.decidedBy === "automated-policy"
      ) {
        decisions.set(item.slug, item as PublicationDecision);
      }
    }

    cache.decisions = decisions;
    return cache.decisions;
  } catch (error) {
    console.error("Failed to load publications:", error);
    cache.decisions = new Map();
    return cache.decisions;
  }
}

/**
 * Get the publication decision for a root slug.
 */
export function getPublication(slug: string): PublicationDecision | null {
  const decisions = loadPublications();
  return decisions.get(slug) ?? null;
}

/**
 * Get all published root slugs (decision === "publish").
 */
export function getPublishedSlugs(): string[] {
  const decisions = loadPublications();
  return [...decisions.values()]
    .filter((d) => d.decision === "publish")
    .map((d) => d.slug);
}

/**
 * Check if morphology publications are available (file exists).
 */
export function arePublicationsAvailable(): boolean {
  return fs.existsSync(PUBLICATIONS_PATH);
}
